INSERT INTO "item_texts" VALUES ('01M647QJXWR8PHM065MCCM7HCV', 'de', 'Transamerican Love Story', 'Transamerican Love Story is an American reality television program in which suitors wooed transgender woman Calpernia Addams. Addams chose a suitor by process of elimination.

Logo, a digital cable channel with LGBT content, originally broadcast the series in 2008 from February through March. Alec Mapa hosted each episode.

Zach Rosen of the Washington Blade praised the series, describing it as "refreshing for its lack of sensationalism".', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXWR8PHM065MCCM7HCV', 'en', 'Transamerican Love Story', 'Transamerican Love Story is an American reality television program in which suitors wooed transgender woman Calpernia Addams. Addams chose a suitor by process of elimination.

Logo, a digital cable channel with LGBT content, originally broadcast the series in 2008 from February through March. Alec Mapa hosted each episode.

Zach Rosen of the Washington Blade praised the series, describing it as "refreshing for its lack of sensationalism".', NULL);
