INSERT INTO "item_texts" VALUES ('01M647QJXXZWYG1SS8BN14NZYA', 'de', 'Folge 1', 'Calpernia meets the eight bachelors.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXXZWYG1SS8BN14NZYA', 'en', 'Getting to Know You', 'Calpernia meets the eight bachelors.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXYSJ3PKAA80RNCD4JF', 'de', 'Folge 2', 'Calpernia''s friends are invited to a Southern dinner which the bachelors must prepare.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXYSJ3PKAA80RNCD4JF', 'en', 'Something''s Cookin''', 'Calpernia''s friends are invited to a Southern dinner which the bachelors must prepare.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXYSJ3PKAA80V3MCBBZ', 'de', 'Folge 3', 'The six remaining suitors must paddle a rubber raft to a yacht in order to win time alone with Calpernia.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXYSJ3PKAA80V3MCBBZ', 'en', 'Love''s a Beach', 'The six remaining suitors must paddle a rubber raft to a yacht in order to win time alone with Calpernia.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXZHQYWGNMDRV4PVBKE', 'de', 'Folge 4', 'Calpernia brings the men to a nightclub where several of her friends evaluate them. Calpernia performs her song "Stunning", and the men learn they will perform on stage and in costume for her and a panel of judges.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJXZHQYWGNMDRV4PVBKE', 'en', 'I Love the Nightlife', 'Calpernia brings the men to a nightclub where several of her friends evaluate them. Calpernia performs her song "Stunning", and the men learn they will perform on stage and in costume for her and a panel of judges.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJY0X87RPZ8Z5JBQTA7C', 'de', 'Folge 5', 'Everyone goes to Oil Can Harry''s to learn to dance the country-western two-step.', NULL);
