INSERT INTO "item_texts" VALUES ('01M647QJY0X87RPZ8Z5KC8WFSJ', 'de', 'Folge 6', 'With Shawn absent for a funeral, only Jim and Mike are left to meet Calpernia''s ''adopted mother'', Chyna.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJY0X87RPZ8Z5KC8WFSJ', 'en', 'Meet The Folks', 'With Shawn absent for a funeral, only Jim and Mike are left to meet Calpernia''s ''adopted mother'', Chyna.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJY1AZ1EMHM192EP1TNX', 'de', 'Where Are They Now?', 'Where Are They Now? is a show hosted by Lydia Shum in 2006, and was shown on TVB in 2006, as well as on Fairchild TV in Canada in 2007 and 2008. Throughout the 32 episodes, Lydia Shum travelled to Taiwan, Japan, USA, and Canada to interview popular celebrities of the 1960s in Hong Kong and Taiwan. Most of these celebrities have now emigrated to foreign countries.', NULL);
INSERT INTO "item_texts" VALUES ('01M647QJY1AZ1EMHM192EP1TNX', 'en', 'Where Are They Now?', 'Where Are They Now? is a show hosted by Lydia Shum in 2006, and was shown on TVB in 2006, as well as on Fairchild TV in Canada in 2007 and 2008. Throughout the 32 episodes, Lydia Shum travelled to Taiwan, Japan, USA, and Canada to interview popular celebrities of the 1960s in Hong Kong and Taiwan. Most of these celebrities have now emigrated to foreign countries.', NULL);
CREATE TABLE media_files (
    id            TEXT    PRIMARY KEY CHECK (length(id) = 26),
    item_id       TEXT    NOT NULL REFERENCES items(id) ON DELETE CASCADE,
    root_id       INTEGER NOT NULL REFERENCES library_roots(id) ON DELETE CASCADE,
    rel_path      TEXT    NOT NULL,
    dev           INTEGER NOT NULL DEFAULT 0,
    inode         INTEGER NOT NULL DEFAULT 0,
    size          INTEGER NOT NULL,
    mtime         INTEGER NOT NULL,
    partial_hash  TEXT,                            -- SHA-256 over first and last 64 KiB plus size
    version_label TEXT,
    container     TEXT    NOT NULL,                -- lower-case extension without dot
    video_codec   TEXT,
    audio_codec   TEXT,
    width         INTEGER,
    height        INTEGER,
    duration_ms   INTEGER,
    probe         TEXT    CHECK (probe IS NULL OR json_valid(probe)),
    keyframes     BLOB,                            -- keyframe index for remux seeking (M1b)
    probed_at     INTEGER,
    keyframes_at  INTEGER,
    missing_since INTEGER,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL, probe_error TEXT, part_index INTEGER CHECK (part_index IS NULL OR part_index >= 1),
    UNIQUE (root_id, rel_path)
) STRICT;
